function renderInventory(){
  const canEdit=['admin','inventory'].includes(currentUser.role);
  const rows=state.inventory.map(p=>{const low=p.stock<=p.minStock; const pct=Math.min(100,Math.max(8,(p.stock/(p.minStock*2))*100));return `<tr><td><strong>${esc(p.sku)}</strong><br><small class="text-muted">${esc(p.id)}</small></td><td><strong>${esc(p.name)}</strong><br><small class="text-muted">${esc(p.category)}</small></td><td><div class="d-flex align-items-center gap-2"><strong class="${low?'text-danger':''}">${p.stock}</strong><div class="stock-bar ${low?'low':''}"><span style="width:${pct}%"></span></div></div><small class="text-muted">Mínimo ${p.minStock}</small></td><td>${esc(p.unit)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${esc(p.supplier)}</td><td>${canEdit?`<button class="action-btn" data-action="stock" data-id="${p.id}"><i class="bi bi-plus-slash-minus"></i></button>`:''}</td></tr>`}).join('');
  const low=state.inventory.filter(p=>p.stock<=p.minStock).length;
  $('#view-inventory').innerHTML=`${pageHead('Repuestos e inventario','Control de existencias, mínimos, costos, precios y proveedores.',canEdit?'<button class="btn btn-primary" data-action="new-part"><i class="bi bi-box-seam me-2"></i>Nuevo repuesto</button>':'')}<div class="alert ${low?'alert-warning':'alert-success'} border-0"><i class="bi bi-exclamation-triangle me-2"></i><strong>${low}</strong> ítems están en nivel mínimo o por debajo.</div><div class="table-card"><div class="table-toolbar"><div><strong>Inventario</strong><div class="small text-muted">${state.inventory.length} referencias</div></div><input class="form-control" style="max-width:280px" placeholder="Buscar repuesto, SKU..." data-table-search="inventory"></div><div class="table-responsive"><table class="table mb-0" id="inventoryTable"><thead><tr><th>SKU</th><th>Repuesto</th><th>Stock</th><th>Unidad</th><th>Costo</th><th>Venta</th><th>Proveedor</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>`;
}

function renderHistory(vehicleFilter=''){
  let rows=filteredHistory(); if(vehicleFilter) rows=rows.filter(h=>h.vehicleId===vehicleFilter);
  $('#view-history').innerHTML=`${pageHead('Historial de mantenimiento','Trazabilidad cronológica de servicios y kilometraje por vehículo.')}<div class="panel mb-3"><div class="row g-2 align-items-end"><div class="col-md-5"><label class="form-label small fw-semibold">Filtrar por vehículo</label><select id="historyVehicle" class="form-select"><option value="">Todos</option>${filteredVehicles().map(v=>`<option value="${v.id}" ${vehicleFilter===v.id?'selected':''}>${esc(v.plate)} · ${esc(v.brand)} ${esc(v.model)}</option>`).join('')}</select></div><div class="col-md-auto"><button class="btn btn-outline-primary" data-action="filter-history">Aplicar</button></div></div></div><div class="panel"><div class="timeline">${rows.sort((a,b)=>b.date.localeCompare(a.date)).map(h=>{const v=getVehicle(h.vehicleId);return `<div class="timeline-item"><div class="d-flex justify-content-between gap-3 flex-wrap"><div><strong>${esc(h.service)}</strong><small>${dateFmt(h.date)} · ${esc(v?.plate||'')} · ${h.odometer.toLocaleString()} km · ${esc(h.technician)}</small><div class="small mt-1">${esc(h.notes)}</div></div><div class="text-end"><strong>${money(h.total)}</strong><small>${esc(h.orderId)}</small></div></div></div>`}).join('')||'<p class="text-muted mb-0">Sin historial para este vehículo.</p>'}</div></div>`;
}

